const compactArt = ["✦ Takt AI ✦"]

const Logo = (props: { theme: TuiThemeCurrent }) => {
  const dim = useTerminalDimensions()
  const compact = createMemo(() => {
    const term = dim()
    return !(term.height >= logoArt.length + 6 && term.width >= 64)
  })

  return (
    <box flexDirection="column" alignItems="center">
      {compact()
        ? <text fg={props.theme.accent}>{compactArt[0]}</text>
        : logoArt.map((row) => (
            <box flexDirection="row">
              {row.map(([text, color]) => (
                <text fg={color || props.theme.accent}>{text}</text>
              ))}
            </box>
          ))}
    </box>
  )
}

const tui: TuiPlugin = async (api) => {
  api.slots.register({
    id,
    order: 100,
    slots: {
      home_logo(ctx) {
        return <Logo theme={ctx.theme.current} />
      },
    },
  })
}

const plugin = { id: "takt-logo", tui }
